pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TicTacToe
 * @notice A gas-optimized, production-ready Tic Tac Toe game on-chain.
 * @dev Implements a 3x3 grid with packed storage for gas efficiency.
 *      Features timeouts to prevent griefing and full event logging.
 */
contract TicTacToe is ReentrancyGuard {
    // -------------------------------------------------------------------------
    // Type Definitions
    // -------------------------------------------------------------------------

    enum GameStatus { PENDING, ACTIVE, DRAW, WON_P1, WON_P2, CANCELLED }

    struct Game {
        address player1;      // Slot 0: Creator (plays X)
        address player2;      // Slot 1: Opponent (plays O)

        // Slot 2: Packed Game State (Hot Path)
        // Storage Layout:
        // [0..31]   timestamp (4 bytes)
        // [32..39]  movesMade (1 byte)
        // [40..47]  status (1 byte)
        // [48..55]  currentTurn (1 byte) - 1 for P1, 2 for P2
        // [56..127] board (9 bytes)
        // Total: 16 bytes (Fits in 1 slot)
        uint32 lastMoveTime;
        uint8 movesMade;
        GameStatus status;
        uint8 currentTurn;    
        uint8[9] board;       // 0=Empty, 1=X (P1), 2=O (P2)
    }

    // -------------------------------------------------------------------------
    // State Variables
    // -------------------------------------------------------------------------

    /// @notice Time allowed per turn before opponent can claim victory
    uint32 public constant TURN_TIMEOUT = 1 hours;

    /// @notice Global counter for game IDs
    uint256 public nextGameId;

    /// @notice Game storage
    mapping(uint256 => Game) public games;

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event GameCreated(uint256 indexed gameId, address indexed creator);
    event GameJoined(uint256 indexed gameId, address indexed opponent);
    event MoveMade(uint256 indexed gameId, address indexed player, uint8 position);
    event GameFinished(uint256 indexed gameId, address indexed winner, string reason);
    event GameCancelled(uint256 indexed gameId);

    // -------------------------------------------------------------------------
    // Errors
    // -------------------------------------------------------------------------

    error InvalidGameId();
    error GameNotPending();
    error GameNotActive();
    error Unauthorized();
    error NotYourTurn();
    error InvalidMove();
    error TimeoutNotReached();
    error CannotJoinOwnGame();

    // -------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------

    constructor() {
        // Empty constructor
    }

    // -------------------------------------------------------------------------
    // Game Lifecycle
    // -------------------------------------------------------------------------

    /// @notice Create a new game and wait for an opponent.
    /// @return gameId The ID of the created game.
    function createGame() external nonReentrant returns (uint256) {
        uint256 gameId = nextGameId++;
        Game storage g = games[gameId];

        g.player1 = msg.sender;
        g.status = GameStatus.PENDING;
        g.lastMoveTime = uint32(block.timestamp);

        emit GameCreated(gameId, msg.sender);
        return gameId;
    }

    /// @notice Join an existing pending game.
    /// @param gameId The ID of the game to join.
    function joinGame(uint256 gameId) external nonReentrant {
        if (gameId >= nextGameId) revert InvalidGameId();
        Game storage g = games[gameId];

        if (g.status != GameStatus.PENDING) revert GameNotPending();
        if (g.player1 == msg.sender) revert CannotJoinOwnGame();

        g.player2 = msg.sender;
        g.status = GameStatus.ACTIVE;
        g.currentTurn = 1; // Player 1 (Creator) starts
        g.lastMoveTime = uint32(block.timestamp);

        emit GameJoined(gameId, msg.sender);
    }

    /// @notice Cancel a pending game. Only creator can cancel.
    function cancelGame(uint256 gameId) external nonReentrant {
        if (gameId >= nextGameId) revert InvalidGameId();
        Game storage g = games[gameId];

        if (g.status != GameStatus.PENDING) revert GameNotPending();
        if (g.player1 != msg.sender) revert Unauthorized();

        g.status = GameStatus.CANCELLED;
        emit GameCancelled(gameId);
    }

    // -------------------------------------------------------------------------
    // Gameplay
    // -------------------------------------------------------------------------

    /// @notice Submit a move to the board.
    /// @param gameId The ID of the game.
    /// @param position The grid index (0-8) to mark.
    function makeMove(uint256 gameId, uint8 position) external nonReentrant {
        if (gameId >= nextGameId) revert InvalidGameId();
        Game storage g = games[gameId];

        if (g.status != GameStatus.ACTIVE) revert GameNotActive();

        // Identify current player
        uint8 playerIdx = g.currentTurn;
        address playerAddr = (playerIdx == 1) ? g.player1 : g.player2;

        if (msg.sender != playerAddr) revert NotYourTurn();
        if (position > 8) revert InvalidMove();
        if (g.board[position] != 0) revert InvalidMove();

        // Apply move
        g.board[position] = playerIdx;
        g.movesMade++;
        g.lastMoveTime = uint32(block.timestamp);

        emit MoveMade(gameId, msg.sender, position);

        // Check outcomes
        if (_checkWin(g.board, playerIdx)) {
            g.status = (playerIdx == 1) ? GameStatus.WON_P1 : GameStatus.WON_P2;
            emit GameFinished(gameId, msg.sender, "Win");
        } else if (g.movesMade == 9) {
            g.status = GameStatus.DRAW;
            emit GameFinished(gameId, address(0), "Draw");
        } else {
            // Switch turn
            g.currentTurn = (playerIdx == 1) ? 2 : 1;
        }
    }

    /// @notice Claim victory if the opponent has exceeded the time limit.
    function claimTimeout(uint256 gameId) external nonReentrant {
        if (gameId >= nextGameId) revert InvalidGameId();
        Game storage g = games[gameId];

        if (g.status != GameStatus.ACTIVE) revert GameNotActive();
        if (block.timestamp <= uint256(g.lastMoveTime) + TURN_TIMEOUT) revert TimeoutNotReached();

        // Current turn holder is the one who timed out
        uint8 timedOutPlayerIdx = g.currentTurn;
        uint8 winnerIdx = (timedOutPlayerIdx == 1) ? 2 : 1;
        address winner = (winnerIdx == 1) ? g.player1 : g.player2;

        // Only winner can claim to prevent third-party interference
        if (msg.sender != winner) revert Unauthorized();

        g.status = (winnerIdx == 1) ? GameStatus.WON_P1 : GameStatus.WON_P2;
        emit GameFinished(gameId, winner, "Timeout");
    }

    // -------------------------------------------------------------------------
    // View Functions
    // -------------------------------------------------------------------------

    /// @notice Get the current board state.
    function getBoard(uint256 gameId) external view returns (uint8[9] memory) {
        return games[gameId].board;
    }

    /// @dev Internal check for win conditions.
    function _checkWin(uint8[9] storage board, uint8 m) internal view returns (bool) {
        // Rows
        if (board[0] == m && board[1] == m && board[2] == m) return true;
        if (board[3] == m && board[4] == m && board[5] == m) return true;
        if (board[6] == m && board[7] == m && board[8] == m) return true;

        // Columns
        if (board[0] == m && board[3] == m && board[6] == m) return true;
        if (board[1] == m && board[4] == m && board[7] == m) return true;
        if (board[2] == m && board[5] == m && board[8] == m) return true;

        // Diagonals
        if (board[0] == m && board[4] == m && board[8] == m) return true;
        if (board[2] == m && board[4] == m && board[6] == m) return true;

        return false;
    }
}

